import java.util.*;
import java.io.*;

public class Main {
    static List<List<Integer>> threeSum(int[] nums) {
        // Write your solution here
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            nums[i] = (int) in.nval;
        }
        List<int[]> out = new ArrayList<>();
        for (List<Integer> t : threeSum(nums)) {
            int[] a = {t.get(0), t.get(1), t.get(2)};
            Arrays.sort(a);
            out.add(a);
        }
        out.sort((p, q) -> p[0] != q[0] ? Integer.compare(p[0], q[0]) : p[1] != q[1] ? Integer.compare(p[1], q[1]) : Integer.compare(p[2], q[2]));
        StringBuilder sb = new StringBuilder();
        sb.append(out.size()).append("\n");
        for (int[] a : out) sb.append(a[0]).append(" ").append(a[1]).append(" ").append(a[2]).append("\n");
        System.out.print(sb);
    }
}
